import{_ as t,o as r,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"CDS Hammer (Day 2) - OSD: Scrub / SnapTrim IO Prioritization","description":"","frontmatter":{"title":"CDS Hammer (Day 2) - OSD: Scrub / SnapTrim IO Prioritization","date":"2014-10-30T00:00:00.000Z","updated":"2014-10-31T00:00:00.000Z","tags":["Ceph","Scrub","SnapTrim","IO Prioritization","OSD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_Hammer_Day_2_-_OSD_-_Scrub_SnapTrim_IO_Prioritization.md","filePath":"posts/2014/CDS_Hammer_Day_2_-_OSD_-_Scrub_SnapTrim_IO_Prioritization.md","lastUpdated":1780459816000}'),a={name:"posts/2014/CDS_Hammer_Day_2_-_OSD_-_Scrub_SnapTrim_IO_Prioritization.md"};function n(_,i,p,e,s,S){return r(),l("div",null,[...i[0]||(i[0]=[o("<p>会议纪要</p><p>会议时间：[请填写会议时间]</p><p>参会人员：Samuel（主讲人），其他研发人员</p><p>会议主题：分布式存储Ceph的 scrub 和 snap trim IO优先级优化</p><p>会议内容：</p><ol><li><p><strong>背景介绍</strong>：</p><ul><li>Ceph中的所有操作都在线程池中执行，但不同线程池之间的相对优先级由操作系统决定，这可能导致不理想的优先级分配。</li><li>为了优化IO优先级，提议将所有可能的IO操作整合到一个队列中，并使用更高效的队列管理方式。</li></ul></li><li><p><strong>主要议题</strong>：</p><ul><li><strong>OSD内部机制</strong>： OSD的绝大多数操作都在线程池中执行，但线程池之间的优先级分配存在问题。</li><li><strong>IO优先级</strong>： 需要优化scrub、snap trim 和恢复等操作的IO优先级。</li><li><strong>恢复线程池</strong>： 当前恢复线程池的线程数量与其他客户端线程数量相比过少，需要调整。</li><li><strong>优先级标记</strong>： 在后台工作中添加IO优先级标记，将优先级管理提升到更高级别。</li></ul></li><li><p><strong>关键细节</strong>：</p><ul><li>使用更高效的队列管理方式，提高队列效率。</li><li>调整恢复线程池的线程数量，优化恢复操作。</li><li>将所有可能的IO操作整合到一个队列中，并使用优先级标记进行管理。</li><li>将操作分解成更小的粒度，提高效率。</li></ul></li><li><p><strong>决定事项</strong>：</p><ul><li>将所有可能的IO操作整合到一个队列中，并使用优先级标记进行管理。</li><li>调整恢复线程池的线程数量，优化恢复操作。</li><li>将操作分解成更小的粒度，提高效率。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>Samuel将在下个月完成相关代码调整。</li><li>检查Lucerne，确认使用tagged union或boost variant。</li><li>优化恢复操作，考虑使用更细粒度的操作分解。</li></ul></li></ol><p><strong>备注</strong>：</p><ul><li>会议中提到的“Firefly”是Ceph的一个版本，指的是Ceph 0.63版本。</li><li>“tagged union”和“boost variant”是Ceph相关的技术术语，分别指Ceph中的一种数据结构和一种编程库。</li></ul><p><strong>关键词</strong>： scrub、snap trim、IO优先级、OSD、线程池、恢复操作、优先级标记、tagged union、boost variant</p>",9)])])}const g=t(a,[["render",n]]);export{m as __pageData,g as default};
